def countMinimalRepairs(s):
    results = []

    def fix(t, si, sj, pair):
        bal = 0
        for i in range(si, len(t)):
            if t[i] == pair[0]:
                bal += 1
            elif t[i] == pair[1]:
                bal -= 1
            if bal >= 0:
                continue
            for j in range(sj, i + 1):
                if t[j] == pair[1] and (j == sj or t[j - 1] != pair[1]):
                    fix(t[:j] + t[j + 1:], i, j, pair)
            return
        rev = t[::-1]
        if pair[0] == "(":
            fix(rev, 0, 0, (")", "("))
        else:
            results.append(rev)

    fix(s, 0, 0, ("(", ")"))
    return len(results)
